        .order-track-stepper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1.5rem;
            background: var(--glamoire-light);
            border-bottom: 1px solid var(--border-color);
            position: relative;
        }

        @media(max-width: 576px) {
            .order-track-stepper {
                display: none;
            }

            /* Hide complex stepper on very small screens */
        }

        .step-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            position: relative;
            z-index: 2;
            flex: 1;
        }

        .step-icon {
            width: 35px;
            height: 35px;
            border-radius: 50%;
            background: #FFF;
            border: 2px solid #D1D5DB;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #9CA3AF;
            font-size: 0.9rem;
            margin-bottom: 8px;
            transition: all 0.3s;
        }

        .step-item.active .step-icon,
        .step-item.done .step-icon {
            background: var(--glamoire-dark);
            border-color: var(--glamoire-dark);
            color: #FFF;
            box-shadow: 0 0 0 4px rgba(24, 48, 24, 0.1);
        }

        .step-text {
            font-size: 0.8rem;
            font-weight: 600;
            color: #9CA3AF;
        }

        .step-item.active .step-text,
        .step-item.done .step-text {
            color: var(--text-main);
        }

        .step-line {
            position: absolute;
            top: 17px;
            left: 50%;
            width: 100%;
            height: 2px;
            background: #D1D5DB;
            z-index: 1;
        }

        .step-item:last-child .step-line {
            display: none;
        }

        .step-item.done .step-line {
            background: var(--glamoire-dark);
        }

        .order-body {
            padding: 1.5rem;
        }

        .order-item-row {
            display: flex;
            flex-wrap: wrap;
            gap: 1.5rem;
            margin-bottom: 1.5rem;
            padding-bottom: 1.5rem;
            border-bottom: 1px dashed var(--border-color);
            align-items: center;
        }

        .order-item-row:last-child {
            margin-bottom: 0;
            padding-bottom: 0;
            border-bottom: none;
        }

        .order-item-img {
            width: 90px;
            height: 90px;
            border-radius: 8px;
            object-fit: cover;
            border: 1px solid var(--border-color);
            cursor: pointer;
            transition: transform 0.3s;
        }

        .order-item-img:hover {
            transform: scale(1.05);
        }

        .order-item-info {
            flex: 1;
            min-width: 200px;
            /* Mencegah teks terlalu sempit */
            cursor: pointer;
        }

        .order-item-brand {
            font-size: 0.75rem;
            color: var(--text-muted);
            text-transform: uppercase;
            font-weight: 700;
            letter-spacing: 0.5px;
        }

        .order-item-name {
            font-size: 1.05rem;
            font-weight: 600;
            color: var(--text-main);
            margin-bottom: 0.2rem;
            line-height: 1.3;
        }

        .order-item-variant {
            font-size: 0.85rem;
            color: var(--text-muted);
            margin-bottom: 0.5rem;
            background: var(--glamoire-light);
            padding: 2px 8px;
            border-radius: 4px;
            display: inline-block;
        }

        .order-item-qty {
            font-size: 0.9rem;
            color: var(--text-main);
            font-weight: 500;
        }

        .order-item-price {
            text-align: right;
            min-width: 120px;
        }

        .order-item-price span {
            display: block;
            font-size: 0.8rem;
            color: var(--text-muted);
            margin-bottom: 4px;
        }

        .order-item-price strong {
            font-size: 1.15rem;
            color: var(--text-main);
        }

        @media (max-width: 576px) {
            .order-item-row {
                flex-direction: column;
                align-items: flex-start;
                gap: 1rem;
            }

            .order-item-price {
                text-align: left;
                width: 100%;
            }
        }

        .order-footer {
            background: #FAFAFA;
            padding: 1.5rem;
            border-top: 1px solid var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
